class Solution {
public:
    bool checkChildrenSum(TreeNode* root) {
        if (root == nullptr) {
            return true;
        }

        if (root->left == nullptr && root->right == nullptr) {
            return true;
        }

        int leftValue = root->left ? root->left->val : 0;
        int rightValue = root->right ? root->right->val : 0;

        if (root->val != leftValue + rightValue) {
            return false;
        }

        return checkChildrenSum(root->left) &&
               checkChildrenSum(root->right);
    }
};
```

Time complexity: `O(n)`, since every node is checked once.

Space complexity: `O(h)` for the recursive call stack, where `h` is the tree height.

